rep(){ local n=$1 c=$2 s=""; for ((i=0;i<n;i++)); do s+="$c"; done; printf '%s' "$s"; }
echo "=== minimal counterexample: 22 chars ==="
s=$(rep 22 "例"); printf 'input=%s  (chars=22, bytes=%d)\n' "$s" ${#s}
/workspace/dataset/test4_executable "$s"
echo "=== 16 chars, 64 bytes ==="
s=$(rep 16 "𝔞"); printf 'chars=16 bytes=%d\n' ${#s}
/workspace/dataset/test4_executable "$s"
